  sr=next(x for x in source['runs'] if x['path']==r['source_run']);last=int(r['actions'][-1]['step'].split('_')[-1]);following=[s for s in sr['steps'] if int(s['step'].split('_')[-1])>last]
  boundary='END_OF_RUN_NO_MORE_COMPLETED_ACTIONS'
  if following and following[0]['execution'].get('status')=='USER_INTERRUPTED':boundary='PARTIAL_ACTION_INTERRUPTED'
